type PublicQuestion = {
  id: string;
  disciplineId: "matematica" | "portugues" | "cultura" | "fisica" | "quimica" | "geometria";
  moduleId: string;
  topic: string;
  type: string;
  difficulty: "Inicial" | "Intermédio" | "Avançado";
  prompt: string;
  options: string[];
  recommendedSeconds: number;
};

const subjectPalette: Record<string, { accent: string; soft: string; label: string }> = {
  matematica: { accent: "#0A36A8", soft: "#E7EDFF", label: "Matemática" },
  portugues: { accent: "#7A3C85", soft: "#F7EAFE", label: "Língua Portuguesa" },
  cultura: { accent: "#087765", soft: "#E2F6F0", label: "Cultura Geral" },
  fisica: { accent: "#BE5B16", soft: "#FFF0E4", label: "Física" },
  quimica: { accent: "#087765", soft: "#E2F6F0", label: "Química" },
  geometria: { accent: "#34495E", soft: "#EDF1F5", label: "Desenho e Geometria" },
};

const formatTime = (seconds: number) => `${Math.floor(seconds / 60).toString().padStart(2, "0")}:${(seconds % 60).toString().padStart(2, "0")}`;

function AppFrame({ children }: { children: React.ReactNode }) {
  return <DashboardLayout>{children}</DashboardLayout>;
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <header className="mb-7 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p className="app-kicker">{eyebrow}</p><h1 className="mt-1 font-display text-3xl tracking-tight text-slate-950 sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">{description}</p></div>{action}</header>;
}

function ProgressBar({ value, tone = "blue" }: { value: number; tone?: "blue" | "violet" | "green" | "amber" }) {
  const colors = { blue: "bg-[#0A36A8]", violet: "bg-[#7A3C85]", green: "bg-[#087765]", amber: "bg-[#E49A1F]" };
  return <div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full ${colors[tone]}`} style={{ width: `${Math.max(0, Math.min(100, value))}%` }} /></div>;
}

function StatCard({ label, value, hint, icon: Icon, tone = "blue" }: { label: string; value: string | number; hint: string; icon: React.ElementType; tone?: "blue" | "violet" | "green" | "amber" }) {
  const colors = { blue: "bg-[#E7EDFF] text-[#0A36A8]", violet: "bg-[#F7EAFE] text-[#7A3C85]", green: "bg-[#E2F6F0] text-[#087765]", amber: "bg-[#FFF3D9] text-[#AA6400]" };
  return <section className="rounded-2xl border border-slate-200/80 bg-white p-5 shadow-[0_10px_30px_rgba(26,42,78,0.035)]"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.12em] text-slate-400">{label}</p><p className="mt-2 text-3xl font-extrabold tracking-tight text-slate-950">{value}</p></div><span className={`grid h-10 w-10 place-items-center rounded-xl ${colors[tone]}`}><Icon className="h-5 w-5" /></span></div><p className="mt-3 text-xs leading-5 text-slate-500">{hint}</p></section>;
}

export function StudentDashboard() {
  const [, setLocation] = useLocation();
  const { user } = useAuth();
  const dashboard = trpc.learning.dashboard.useQuery();
  const data = dashboard.data;
  return <AppFrame>{dashboard.isLoading ? <DashboardSkeleton /> : <>
    <PageHeading eyebrow="Visão geral" title={`Olá, ${data?.profile?.displayName || user?.name?.split(" ")[0] || "estudante"}.`} description="O seu percurso é construído a partir do que estuda, pratica e revê — não apenas do que abre." action={<div className="flex flex-wrap gap-2"><Button onClick={() => setLocation(data?.next ? `/app/aula/${data.next.moduleId}` : "/app/estudar")} className="rounded-xl bg-[#0A36A8] text-white hover:bg-[#092e90]"><Play className="mr-2 h-4 w-4" />{data?.next ? "Continuar percurso" : "Explorar programa"}</Button><PdfExportModal triggerButton={<Button variant="outline" className="gap-2 rounded-xl border-[#BFD0FF] bg-[#F1F5FF] text-[#0A36A8] hover:bg-[#E7EDFF]"><FileText className="h-4 w-4" />Guia em PDF</Button>} /><ShareInviteButton compact className="bg-[#E7EDFF] text-[#0A36A8] hover:bg-[#D8E2FF] hover:text-[#0A36A8]" /></div>} />
    {!data?.profile && <section className="mb-6 flex flex-col gap-4 rounded-2xl border border-[#D8E2FF] bg-[#F1F5FF] p-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex gap-3"><CircleAlert className="mt-0.5 h-5 w-5 shrink-0 text-[#0A36A8]" /><div><p className="font-bold text-slate-900">Complete o seu perfil de preparação</p><p className="mt-1 text-sm text-slate-600">Defina o tempo diário e a meta para receber um plano de estudo mais útil.</p></div></div><Button variant="outline" onClick={() => setLocation("/app/perfil")} className="rounded-xl border-[#BFD0FF] bg-white text-[#0A36A8]">Configurar perfil</Button></section>}
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><StatCard label="Preparação" value={`${data?.stats.preparationIndex ?? 0}%`} hint="Índice de domínio actual." icon={Target} /><StatCard label="Questões" value={data?.stats.answered ?? 0} hint="Respostas guardadas." icon={ListChecks} tone="violet" /><StatCard label="Taxa de acerto" value={`${data?.stats.accuracy ?? 0}%`} hint="Com base nas tentativas." icon={Trophy} tone="green" /><StatCard label="Sequência" value={`${data?.stats.streak ?? 0} ${data?.stats.streak === 1 ? "dia" : "dias"}`} hint="Dias consecutivos com actividade de estudo." icon={CalendarClock} tone="violet" /><StatCard label="Módulos concluídos" value={`${data?.stats.completed ?? 0}/${data?.stats.totalModules ?? 0}`} hint="Aulas marcadas como concluídas." icon={CheckCircle2} tone="amber" /></section>
    <section className="mt-6 grid gap-6 xl:grid-cols-[1.45fr_0.8fr]"><div className="rounded-3xl bg-[#0D1C4D] p-6 text-white shadow-[0_22px_55px_rgba(13,28,77,0.18)] sm:p-8"><p className="app-kicker text-[#FFCC5C]">Próxima acção recomendada</p><h2 className="mt-3 max-w-xl font-display text-3xl">{data?.next?.title || "Comece pelo programa oficial."}</h2><p className="mt-3 max-w-xl text-sm leading-6 text-blue-100">{data?.next?.reason || "Escolha uma disciplina para iniciar a sua preparação de forma estruturada."}</p><div className="mt-6 flex items-center gap-4"><div className="min-w-0 flex-1"><div className="mb-2 flex justify-between text-xs text-blue-100"><span>Domínio actual</span><span>{data?.next?.mastery ?? 0}%</span></div><ProgressBar value={data?.next?.mastery ?? 0} tone="amber" /></div><Button onClick={() => setLocation(data?.next ? `/app/aula/${data.next.moduleId}` : "/app/estudar")} className="shrink-0 rounded-xl bg-white text-[#0A36A8] hover:bg-blue-50"><ArrowRight className="mr-1 h-4 w-4" />Estudar</Button></div></div>
    <section className="mt-6 grid gap-4 md:grid-cols-2"><article className="rounded-2xl border border-emerald-100 bg-emerald-50 p-5"><p className="app-kicker text-[#087765]">Ponto forte</p><h2 className="mt-2 font-display text-2xl text-slate-950">{data?.strengths?.mastery ? data.strengths.label : "Ainda a construir"}</h2><p className="mt-2 text-sm leading-6 text-slate-700">{data?.strengths?.mastery ? `${data.strengths.mastery}% de domínio médio nesta disciplina. Mantenha a consistência com uma prática curta.` : "Comece por uma aula e uma questão de treino para formar o seu primeiro ponto forte."}</p></article><article className="rounded-2xl border border-amber-100 bg-[#FFFAEF] p-5"><p className="app-kicker text-[#C77A00]">Ponto a desenvolver</p><h2 className="mt-2 font-display text-2xl text-slate-950">{data?.improvements?.label || "Escolha uma disciplina"}</h2><p className="mt-2 text-sm leading-6 text-slate-700">{data?.improvements ? `${data.improvements.mastery}% de domínio médio. Use a próxima acção recomendada para transformar esta área em progresso.` : "O diagnóstico aparece depois das primeiras actividades."}</p></article></section>
      <div className="rounded-3xl border border-slate-200 bg-white p-6"><div className="flex items-center justify-between"><h2 className="font-display text-2xl text-slate-950">Por disciplina</h2><button onClick={() => setLocation("/app/progresso")} className="text-xs font-bold text-[#0A36A8]">Ver detalhes</button></div><div className="mt-6 space-y-5">{data?.byDiscipline.map((subject) => <div key={subject.id}><div className="mb-2 flex items-center justify-between text-sm"><span className="font-bold text-slate-700">{subject.label}</span><span className="font-extrabold text-slate-950">{subject.mastery}%</span></div><ProgressBar value={subject.mastery} tone={subject.id === "matematica" ? "blue" : subject.id === "portugues" ? "violet" : "green"} /></div>)}</div></div></section>
    <section className="mt-6 grid gap-5 lg:grid-cols-3"><QuickAction icon={BookOpen} title="Estudar módulos" description="Aulas, conceitos, exemplos e tópicos oficiais." onClick={() => setLocation("/app/estudar")} /><QuickAction icon={TimerReset} title="Fazer um simulado" description="Cronómetro, marcação e relatório ao terminar." onClick={() => setLocation("/app/simulados")} /><QuickAction icon={BrainCircuit} title="Perguntar ao LUANDA AI" description="Pistas e explicações que respeitam o seu contexto." onClick={() => setLocation("/app/ia")} /></section>
  </>}</AppFrame>;
}

function DashboardSkeleton() { return <div className="space-y-6"><div className="h-28 animate-pulse rounded-3xl bg-slate-200" /><div className="grid grid-cols-2 gap-4 xl:grid-cols-4">{Array.from({ length: 4 }).map((_, i) => <div key={i} className="h-40 animate-pulse rounded-2xl bg-slate-200" />)}</div><div className="grid gap-6 xl:grid-cols-2"><div className="h-60 animate-pulse rounded-3xl bg-slate-200" /><div className="h-60 animate-pulse rounded-3xl bg-slate-200" /></div></div>; }
function QuickAction({ icon: Icon, title, description, onClick }: { icon: React.ElementType; title: string; description: string; onClick: () => void }) { return <button onClick={onClick} className="group rounded-2xl border border-slate-200 bg-white p-5 text-left transition-all hover:-translate-y-0.5 hover:border-[#BFD0FF] hover:shadow-lg"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#E7EDFF] text-[#0A36A8]"><Icon className="h-5 w-5" /></span><p className="mt-4 font-bold text-slate-900">{title}</p><p className="mt-1 text-sm leading-5 text-slate-500">{description}</p><span className="mt-4 inline-flex items-center text-xs font-bold text-[#0A36A8]">Abrir <ChevronRight className="ml-1 h-3 w-3 transition-transform group-hover:translate-x-0.5" /></span></button>; }

export function StudyPage() {
  const [, setLocation] = useLocation();
  const catalog = trpc.learning.catalog.useQuery();
  const progress = trpc.learning.dashboard.useQuery();
  const favorites = trpc.learning.resources.favorites.useQuery();
  const toggleFavorite = trpc.learning.resources.toggleFavorite.useMutation({ onSuccess: () => favorites.refetch() });
  const [subject, setSubject] = useState("all");
  const [query, setQuery] = useState("");
  const allModules = catalog.data?.modules || [];
  const modules = allModules.filter((module) => (subject === "all" || module.disciplineId === subject) && `${module.title} ${module.description} ${module.officialTopics.join(" ")}`.toLowerCase().includes(query.toLowerCase()));
  const disciplineQuestionCounts = allModules.reduce<Record<string, number>>((counts, module) => ({ ...counts, [module.disciplineId]: (counts[module.disciplineId] ?? 0) + module.exerciseCount }), {});
  const moduleProgress = new Map((progress.data?.moduleProgress || []).map((item) => [item.module.id, item]));
  const favoriteIds = new Set((favorites.data || []).filter((item) => item.resourceType === "module").map((item) => item.resourceId));
  return <AppFrame><PageHeading eyebrow="Programa de estudo" title="Escolha o que estudar agora." description="Os módulos seguem a estrutura do programa fornecido. As aulas e questões apresentadas são materiais de preparação, identificados como complementares quando aplicável." action={<div className="flex flex-wrap items-center gap-2"><PdfExportModal /><div className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2"><BookMarked className="h-4 w-4 text-[#0A36A8]" /><span className="text-xs font-semibold text-slate-600">{catalog.data?.totalTrainingQuestions ?? 0} questões de treino</span></div></div>} />
    <section className="sticky top-0 z-20 mb-6 rounded-2xl border border-slate-200/80 bg-white/95 p-3 shadow-sm backdrop-blur"><div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div className="flex gap-2 overflow-x-auto pb-1 lg:pb-0">{(["all", "matematica", "fisica", "quimica", "geometria", "portugues", "cultura"] as const).map((item) => <button key={item} onClick={() => setSubject(item)} className={`shrink-0 rounded-xl px-3 py-2 text-sm font-bold transition-colors ${subject === item ? "bg-[#0A36A8] text-white" : "bg-slate-50 text-slate-600 hover:bg-slate-100"}`}>{item === "all" ? `Todas (${catalog.data?.totalTrainingQuestions ?? 0})` : `${subjectPalette[item].label} (${disciplineQuestionCounts[item] ?? 0})`}</button>)}</div><Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Pesquisar módulo ou tópico" className="h-10 max-w-sm rounded-xl border-slate-200" /></div></section>
    <section className="grid gap-4 md:grid-cols-2 2xl:grid-cols-3">{modules.map((module) => { const palette = subjectPalette[module.disciplineId]; const state = moduleProgress.get(module.id); const favorited = favoriteIds.has(module.id); return <article key={module.id} className="group relative overflow-hidden rounded-3xl border border-slate-200 bg-white p-5 shadow-[0_10px_30px_rgba(26,42,78,0.03)] transition-all hover:-translate-y-0.5 hover:shadow-lg"><div className="absolute inset-x-0 top-0 h-1.5" style={{ background: palette.accent }} /><div className="flex items-start justify-between pt-2"><div><span className="rounded-full px-2.5 py-1 text-[0.65rem] font-extrabold uppercase tracking-[0.12em]" style={{ background: palette.soft, color: palette.accent }}>{module.discipline}</span><h2 className="mt-4 font-display text-2xl leading-tight text-slate-950">{module.title}</h2></div><button onClick={() => toggleFavorite.mutate({ resourceType: "module", resourceId: module.id })} aria-label="Guardar módulo" className={`grid h-9 w-9 place-items-center rounded-xl transition-colors ${favorited ? "bg-[#FFF3D9] text-[#B56D00]" : "bg-slate-50 text-slate-400 hover:text-[#B56D00]"}`}><Star className={`h-4 w-4 ${favorited ? "fill-current" : ""}`} /></button></div><p className="mt-3 min-h-12 text-sm leading-6 text-slate-600">{module.description}</p><div className="mt-5 flex flex-wrap gap-2">{module.officialTopics.slice(0, 3).map((topic) => <span key={topic} className="rounded-lg bg-slate-50 px-2 py-1 text-[0.68rem] font-medium text-slate-500">{topic}</span>)}{module.officialTopics.length > 3 && <span className="rounded-lg bg-slate-50 px-2 py-1 text-[0.68rem] font-medium text-slate-500">+{module.officialTopics.length - 3}</span>}</div><div className="mt-4 inline-flex items-center rounded-lg px-2.5 py-1 text-xs font-bold" style={{ background: palette.soft, color: palette.accent }}><ListChecks className="mr-1 h-3.5 w-3.5" />{module.exerciseCount} {module.exerciseCount === 1 ? "questão de treino" : "questões de treino"}</div><div className="mt-5"><div className="mb-2 flex justify-between text-xs text-slate-500"><span>{state?.status === "completed" ? "Concluído" : state?.status === "in_progress" ? "Em curso" : "Não iniciado"}</span><span>{state?.mastery ?? 0}% domínio</span></div><ProgressBar value={state?.mastery ?? 0} tone={module.disciplineId === "matematica" ? "blue" : module.disciplineId === "portugues" ? "violet" : "green"} /></div><div className="mt-5 flex items-center justify-between"><span className="inline-flex items-center text-xs font-semibold text-slate-500"><Clock3 className="mr-1 h-3.5 w-3.5" />{module.estimatedMinutes} min</span><Button onClick={() => setLocation(`/app/aula/${module.id}`)} size="sm" className="rounded-xl" style={{ background: palette.accent }}>Abrir aula <ArrowRight className="ml-1 h-3.5 w-3.5" /></Button></div></article>; })}</section>{!modules.length && <EmptyState icon={BookOpen} title="Nenhum módulo encontrado" description="Ajuste a pesquisa ou escolha outra disciplina." />}</AppFrame>;
}

export function LessonPage() {
  const [, params] = useRoute("/app/aula/:moduleId");
  const [, setLocation] = useLocation();
  const moduleId = params?.moduleId ?? "";
  const lesson = trpc.learning.lesson.useQuery({ moduleId });
  const questions = trpc.learning.questions.list.useQuery({ moduleId });
  const notes = trpc.learning.resources.notes.useQuery({ moduleId });
  const utils = trpc.useUtils();
  const update = trpc.learning.progress.update.useMutation({ onSuccess: () => { utils.learning.dashboard.invalidate(); utils.learning.catalog.invalidate(); } });
  const saveNote = trpc.learning.resources.saveNote.useMutation({ onSuccess: () => { notes.refetch(); setNote(""); } });
  const [note, setNote] = useState("");
  const [quickCheckVisible, setQuickCheckVisible] = useState(false);
  const module = lesson.data;
  useEffect(() => setQuickCheckVisible(false), [moduleId]);
  if (lesson.isLoading) return <AppFrame><DashboardSkeleton /></AppFrame>;
  if (!module) return <AppFrame><EmptyState icon={CircleAlert} title="Módulo não encontrado" description="Volte ao programa e escolha outra aula." action={<Button onClick={() => setLocation("/app/estudar")}>Ver programa</Button>} /></AppFrame>;
  const palette = subjectPalette[module.disciplineId];
  return <AppFrame><button onClick={() => setLocation("/app/estudar")} className="mb-5 inline-flex items-center text-sm font-bold text-slate-500 hover:text-[#0A36A8]"><ArrowLeft className="mr-1 h-4 w-4" />Programa de estudo</button><section className="overflow-hidden rounded-3xl border border-slate-200 bg-white"><div className="p-6 sm:p-9" style={{ background: `linear-gradient(135deg, ${palette.soft}, #fff 70%)` }}><p className="app-kicker" style={{ color: palette.accent }}>{module.discipline} · Conteúdo oficial</p><h1 className="mt-2 max-w-3xl font-display text-4xl text-slate-950 sm:text-5xl">{module.lesson.title}</h1><p className="mt-4 max-w-2xl text-base leading-7 text-slate-600">{module.lesson.objective}</p><div className="mt-6 flex flex-wrap gap-3"><span className="rounded-full bg-white px-3 py-1.5 text-xs font-bold text-slate-600 shadow-sm"><Clock3 className="mr-1 inline h-3.5 w-3.5" />{module.estimatedMinutes} min</span><span className="rounded-full bg-white px-3 py-1.5 text-xs font-bold text-slate-600 shadow-sm">Nível {module.difficulty}</span><span className="rounded-full bg-white px-3 py-1.5 text-xs font-bold text-slate-600 shadow-sm">Questões de treino disponíveis</span></div></div><div className="grid gap-8 p-6 sm:p-9 xl:grid-cols-[1fr_320px]"><article className="space-y-8"><section><h2 className="font-display text-3xl text-slate-950">Conceito</h2><p className="mt-3 text-[1.02rem] leading-8 text-slate-700">{module.lesson.explanation}</p></section>{module.lesson.concepts?.length ? <section className="rounded-2xl border border-[#D8E2FF] bg-[#F4F7FF] p-5"><p className="app-kicker text-[#0A36A8]">Definições essenciais</p><div className="mt-4 grid gap-3">{module.lesson.concepts.map((concept) => <div key={concept.term} className="rounded-xl border border-white/80 bg-white/80 p-4"><h3 className="font-bold text-slate-950">{concept.term}</h3><p className="mt-1 text-sm leading-6 text-slate-700">{concept.definition}</p><p className="mt-2 text-xs font-semibold leading-5 text-[#0A36A8]">Como usar: {concept.application}</p></div>)}</div></section> : null}{module.lesson.topicSessions?.length ? <section><p className="app-kicker" style={{ color: palette.accent }}>Sessões por tópico oficial</p><h2 className="mt-1 font-display text-3xl text-slate-950">Estude o programa tema a tema.</h2><div className="mt-5 space-y-3">{module.lesson.topicSessions.map((session, index) => <details key={session.topic} open={index === 0} className="group rounded-2xl border border-slate-200 bg-white p-4"><summary className="cursor-pointer list-none font-bold text-slate-900"><span className="mr-2 inline-flex h-6 w-6 items-center justify-center rounded-full text-xs font-extrabold text-white" style={{ background: palette.accent }}>{index + 1}</span>{session.topic}<span className="ml-2 text-xs font-medium text-slate-400">Abrir sessão</span></summary><div className="mt-4 border-t border-slate-100 pt-4"><p className="text-sm font-bold text-slate-800">{session.focus}</p><p className="mt-2 text-sm leading-6 text-slate-600">{session.explanation}</p><div className="mt-3 grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-[#F4F7FF] p-3"><p className="text-xs font-extrabold uppercase tracking-[0.1em] text-[#0A36A8]">Definição do tópico</p><p className="mt-1 text-sm leading-6 text-slate-700">{session.definition}</p></div><div className="rounded-xl bg-emerald-50 p-3"><p className="text-xs font-extrabold uppercase tracking-[0.1em] text-[#087765]">Exemplo de aplicação</p><p className="mt-1 text-sm leading-6 text-slate-700">{session.example}</p></div></div><div className="mt-3 rounded-xl bg-slate-50 p-3"><p className="text-xs font-extrabold uppercase tracking-[0.1em] text-slate-400">Pergunta de confirmação</p><p className="mt-1 text-sm font-semibold text-slate-800">{session.checkpoint}</p><p className="mt-2 text-sm leading-6 text-slate-600">Resposta explicada: {session.answer}</p></div><p className="mt-3 text-xs font-bold" style={{ color: palette.accent }}>Prática sugerida: {session.practiceAction}</p></div></details>)}</div></section> : null}{module.lesson.formula && <section className="rounded-2xl border border-[#D8E2FF] bg-[#F4F7FF] p-5"><p className="app-kicker text-[#0A36A8]">Fórmula de apoio</p>{module.lesson.formulaLatex ? <BlockMath math={module.lesson.formulaLatex} /> : <p className="mt-3 font-mono text-lg font-bold text-[#0A36A8]">{module.lesson.formula}</p>}</section>}<section><h2 className="font-display text-3xl text-slate-950">Passo a passo</h2><ol className="mt-5 space-y-3">{module.lesson.steps.map((step, index) => <li key={step} className="flex gap-3 rounded-xl border border-slate-100 bg-slate-50 p-4"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full text-xs font-extrabold text-white" style={{ background: palette.accent }}>{index + 1}</span><p className="pt-0.5 text-sm leading-6 text-slate-700">{step}</p></li>)}</ol></section>{module.lesson.examples?.map((example) => <section key={example.title} className="rounded-2xl border border-emerald-100 bg-emerald-50/70 p-5"><p className="app-kicker text-[#087765]">{example.title}</p><h3 className="mt-2 text-lg font-bold text-slate-950">{example.prompt}</h3><p className="mt-3 text-sm leading-6 text-slate-700">{example.walkthrough}</p></section>)}{module.lesson.quickCheck && <section className="rounded-2xl border border-violet-100 bg-[#FAF6FF] p-5"><p className="app-kicker text-[#7A3C85]">Verificação rápida</p><h3 className="mt-2 text-lg font-bold text-slate-950">{module.lesson.quickCheck.prompt}</h3>{quickCheckVisible ? <p className="mt-3 rounded-xl bg-white p-3 text-sm leading-6 text-slate-700">{module.lesson.quickCheck.answer}</p> : <Button variant="outline" onClick={() => setQuickCheckVisible(true)} className="mt-4 rounded-xl border-violet-200 text-[#7A3C85]">Ver resposta</Button>}</section>}<section className="grid gap-4 sm:grid-cols-2"><div className="rounded-2xl border border-amber-100 bg-[#FFFAEF] p-5"><Lightbulb className="h-5 w-5 text-[#C77A00]" /><h3 className="mt-3 font-bold text-slate-900">Dica de exame</h3><p className="mt-2 text-sm leading-6 text-slate-600">{module.lesson.examTip}</p></div><div className="rounded-2xl border border-rose-100 bg-[#FFF5F5] p-5"><CircleAlert className="h-5 w-5 text-[#BD3F45]" /><h3 className="mt-3 font-bold text-slate-900">Erro comum</h3><p className="mt-2 text-sm leading-6 text-slate-600">{module.lesson.commonError}</p></div></section><section className="rounded-2xl bg-[#0D1C4D] p-6 text-white"><p className="app-kicker text-[#FFCC5C]">Prossiga com prática</p><h3 className="mt-2 font-display text-2xl">Transforme a explicação em acerto.</h3><p className="mt-2 text-sm leading-6 text-blue-100">Há {questions.data?.length ?? 0} questões de treino associadas a este módulo. As questões são complementares e não oficiais.</p><div className="mt-5 flex flex-wrap gap-3"><Button onClick={() => setLocation(`/app/praticar?module=${module.id}`)} className="rounded-xl bg-white text-[#0A36A8] hover:bg-blue-50">Praticar agora <ArrowRight className="ml-1 h-4 w-4" /></Button><Button onClick={() => setLocation(`/app/ia?module=${module.id}`)} variant="outline" className="rounded-xl border-blue-300 bg-transparent text-white hover:bg-white/10 hover:text-white"><MessageCircleQuestion className="mr-1 h-4 w-4" />Pedir ajuda ao LUANDA AI</Button><Button variant="outline" onClick={() => update.mutate({ moduleId: module.id, status: "completed", completionPercent: 100, currentLessonId: module.lesson.id })} disabled={update.isPending} className="rounded-xl border-blue-300 bg-transparent text-white hover:bg-white/10 hover:text-white"><Check className="mr-1 h-4 w-4" />Marcar aula concluída</Button></div></section></article><aside className="space-y-5"><section className="rounded-2xl border border-slate-200 bg-slate-50 p-5"><p className="app-kicker text-slate-400">Tópicos do programa</p><ul className="mt-4 space-y-3">{module.officialTopics.map((topic) => <li key={topic} className="flex gap-2 text-sm leading-5 text-slate-700"><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full" style={{ background: palette.accent }} />{topic}</li>)}</ul></section><section className="rounded-2xl border border-slate-200 bg-white p-5"><p className="app-kicker text-slate-400">Minhas anotações</p><Textarea value={note} onChange={(event) => setNote(event.target.value)} className="mt-4 min-h-28 rounded-xl" placeholder="Registe uma dúvida, fórmula ou lembrete…" /><Button onClick={() => saveNote.mutate({ moduleId: module.id, body: note })} disabled={!note.trim() || saveNote.isPending} size="sm" className="mt-3 rounded-xl">Guardar nota</Button><div className="mt-4 space-y-3">{notes.data?.slice(0, 3).map((item) => <p key={item.id} className="rounded-lg bg-slate-50 p-3 text-xs leading-5 text-slate-600">{item.body}</p>)}</div></section></aside></div></section></AppFrame>;
}

function QuestionWorkspace({ question, onNext, onAnswer, onRetry, result, busy, mode = "practice", favorited = false, onToggleFavorite }: { question: PublicQuestion; onNext: () => void; onAnswer: (response: { selectedOption?: number; answer?: string }) => void; onRetry?: () => void; result?: { isCorrect: boolean; correctOption: number; explanation: string; errorHint?: string; recommendation?: string } | null; busy: boolean; mode?: "practice" | "exam"; favorited?: boolean; onToggleFavorite?: () => void }) {
  const [selected, setSelected] = useState<number | null>(null);
  const [textAnswer, setTextAnswer] = useState("");
  useEffect(() => { setSelected(null); setTextAnswer(""); }, [question.id]);
  const palette = subjectPalette[question.disciplineId];
  const freeResponse = question.type === "numeric" || question.type === "short_answer";
  return <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-[0_12px_35px_rgba(26,42,78,0.04)] sm:p-8"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><span className="rounded-full px-2.5 py-1 text-[0.65rem] font-extrabold uppercase tracking-[0.12em]" style={{ background: palette.soft, color: palette.accent }}>{palette.label}</span><span className="rounded-full bg-slate-100 px-2.5 py-1 text-[0.65rem] font-bold text-slate-500">{question.difficulty}</span></div><div className="flex items-center gap-2"><span className="inline-flex items-center text-xs font-semibold text-slate-500"><Clock3 className="mr-1 h-3.5 w-3.5" />~{question.recommendedSeconds}s</span>{mode === "practice" && onToggleFavorite ? <button onClick={onToggleFavorite} className={`grid h-9 w-9 place-items-center rounded-xl ${favorited ? "bg-[#FFF3D9] text-[#B56D00]" : "bg-slate-100 text-slate-500 hover:text-[#B56D00]"}`} aria-label="Guardar questão"><Star className={`h-4 w-4 ${favorited ? "fill-current" : ""}`} /></button> : null}</div></div><p className="mt-4 text-xs font-bold uppercase tracking-[0.14em] text-slate-400">{mode === "exam" ? "Questão do simulado" : "Questão de treino"} · {question.topic}</p><h2 className="mt-3 max-w-3xl text-xl font-bold leading-8 text-slate-950 sm:text-2xl">{question.prompt}</h2>{freeResponse ? <div className="mt-6"><Label htmlFor={`answer-${question.id}`}>{question.type === "numeric" ? "Resposta numérica" : "Resposta curta"}</Label>{question.type === "numeric" ? <Input id={`answer-${question.id}`} inputMode="decimal" value={textAnswer} onChange={(event) => setTextAnswer(event.target.value)} disabled={Boolean(result)} className="mt-2 h-12 rounded-xl" placeholder="Escreva a sua resposta" /> : <Textarea id={`answer-${question.id}`} value={textAnswer} onChange={(event) => setTextAnswer(event.target.value)} disabled={Boolean(result)} className="mt-2 min-h-24 rounded-xl" placeholder="Escreva uma resposta curta" />}</div> : <div className="mt-6 grid gap-3">{question.options.map((option, index) => { const isSelected = selected === index; const className = result ? index === result.correctOption ? "border-emerald-400 bg-emerald-50 text-emerald-900" : isSelected ? "border-rose-300 bg-rose-50 text-rose-900" : "border-slate-200 text-slate-500" : isSelected ? "border-[#0A36A8] bg-[#EEF2FF] text-[#0A36A8]" : "border-slate-200 bg-white text-slate-700 hover:border-[#BFD0FF] hover:bg-[#F6F8FF]"; return <button key={option} disabled={Boolean(result)} onClick={() => setSelected(index)} className={`flex items-start gap-3 rounded-2xl border p-4 text-left text-sm font-medium transition-colors disabled:cursor-default ${className}`}><span className="grid h-6 w-6 shrink-0 place-items-center rounded-full border border-current text-xs font-extrabold">{String.fromCharCode(65 + index)}</span><span className="pt-0.5 leading-6">{option}</span></button>; })}</div>}{result && mode === "practice" && <div className={`mt-5 rounded-2xl p-5 ${result.isCorrect ? "bg-emerald-50" : "bg-rose-50"}`}><div className="flex gap-3"><span className={`grid h-8 w-8 shrink-0 place-items-center rounded-full ${result.isCorrect ? "bg-emerald-600" : "bg-rose-500"} text-white`}>{result.isCorrect ? <Check className="h-4 w-4" /> : <X className="h-4 w-4" />}</span><div><p className="font-bold text-slate-950">{result.isCorrect ? "Resposta correcta." : "Ainda não foi desta vez."}</p><p className="mt-2 text-sm leading-6 text-slate-700">{result.explanation}</p>{!result.isCorrect && <p className="mt-2 text-sm font-semibold text-slate-700">Pista para a próxima tentativa: {result.errorHint}</p>}</div></div></div>}<div className="mt-6 flex flex-wrap items-center gap-3">{!result ? <Button disabled={(freeResponse ? !textAnswer.trim() : selected === null) || busy} onClick={() => freeResponse ? onAnswer({ answer: textAnswer }) : selected !== null && onAnswer({ selectedOption: selected })} className="rounded-xl bg-[#0A36A8] text-white hover:bg-[#092e90]">{busy ? "A corrigir…" : mode === "exam" ? "Guardar resposta" : "Corrigir resposta"}</Button> : <><Button onClick={onNext} className="rounded-xl bg-[#0A36A8] text-white hover:bg-[#092e90]">Próxima questão <ArrowRight className="ml-1 h-4 w-4" /></Button>{!result.isCorrect && onRetry ? <Button variant="outline" onClick={onRetry} className="rounded-xl">Tentar novamente <RotateCcw className="ml-1 h-4 w-4" /></Button> : null}</>}{mode === "practice" && <Link href={`/app/ia?module=${question.moduleId}&question=${question.id}`} className="inline-flex items-center rounded-xl border border-[#BFD0FF] px-3 py-2 text-sm font-bold text-[#0A36A8] hover:bg-[#F3F6FF]"><MessageCircleQuestion className="mr-1.5 h-4 w-4" />Pedir uma pista</Link>}</div></section>;
}

export function PracticePage() {
  const params = new URLSearchParams(typeof window === "undefined" ? "" : window.location.search);
  const moduleId = params.get("module") || undefined;
  const questionId = params.get("question") || undefined;
  const challengeDiscipline = params.get("discipline") as "matematica" | "fisica" | "quimica" | "geometria" | "portugues" | "cultura" | null;
  const isDailyChallenge = params.get("daily") === "1";
  const challengeDifficulty = params.get("difficulty") as "Inicial" | "Intermédio" | "Avançado" | null;
  const [subject, setSubject] = useState<"all" | "matematica" | "fisica" | "quimica" | "geometria" | "portugues" | "cultura">(challengeDiscipline ?? "all");
  const [difficulty, setDifficulty] = useState<"all" | "Inicial" | "Intermédio" | "Avançado">(challengeDifficulty ?? "all");
  const [onlyIncorrect, setOnlyIncorrect] = useState(params.get("errors") === "1");
  const [onlyUnanswered, setOnlyUnanswered] = useState(false);
  const [favoritesOnly, setFavoritesOnly] = useState(false);
  const [selectedModule, setSelectedModule] = useState(moduleId ?? "all");
  const [selectedTopic, setSelectedTopic] = useState("all");
  const catalog = trpc.learning.catalog.useQuery();
  const favorites = trpc.learning.resources.favorites.useQuery();
  const toggleFavorite = trpc.learning.resources.toggleFavorite.useMutation({ onSuccess: () => { favorites.refetch(); query.refetch(); } });
  const utils = trpc.useUtils();
  const completeDaily = trpc.learning.challenges.completeDaily.useMutation({ onSuccess: () => utils.learning.challenges.today.invalidate() });
  const query = trpc.learning.questions.list.useQuery({ questionId, moduleId: questionId ? undefined : selectedModule === "all" ? undefined : selectedModule, topic: questionId ? undefined : selectedTopic === "all" ? undefined : selectedTopic, disciplineId: questionId ? undefined : subject === "all" ? undefined : subject, difficulty: questionId ? undefined : difficulty === "all" ? undefined : difficulty, onlyIncorrect: questionId ? false : onlyIncorrect, onlyUnanswered: questionId ? false : onlyUnanswered, favoritesOnly: questionId ? false : favoritesOnly });
  const submit = trpc.learning.questions.submit.useMutation({ onSuccess: (response, variables) => { setResult(response); utils.learning.dashboard.invalidate(); utils.learning.review.invalidate(); if (isDailyChallenge && variables.questionId === questionId) completeDaily.mutate({ questionId: variables.questionId }); } });
  const [index, setIndex] = useState(0);
  const [result, setResult] = useState<ReturnType<typeof submit.mutate> extends never ? null : any>(null);
  useEffect(() => { setIndex(0); setResult(null); }, [subject, difficulty, onlyIncorrect, onlyUnanswered, favoritesOnly, selectedModule, selectedTopic, questionId]);
  useEffect(() => { if (challengeDiscipline) setSubject(challengeDiscipline); }, [challengeDiscipline]);
  const availableModules = (catalog.data?.modules ?? []).filter((module) => subject === "all" || module.disciplineId === subject);
  const moduleTopics = availableModules.find((module) => module.id === selectedModule)?.officialTopics ?? [];
  const favoriteQuestionIds = new Set((favorites.data ?? []).filter((item) => item.resourceType === "question").map((item) => item.resourceId));
  const questions = (query.data || []) as PublicQuestion[];
  const question = questions[Math.min(index, Math.max(questions.length - 1, 0))];
  const [questionStartedAt, setQuestionStartedAt] = useState(Date.now());
  useEffect(() => { setQuestionStartedAt(Date.now()); }, [question?.id]);
  const answer = (response: { selectedOption?: number; answer?: string }) => { if (!question) return; submit.mutate({ questionId: question.id, ...response, durationSeconds: Math.min(3600, Math.max(1, Math.round((Date.now() - questionStartedAt) / 1000))) }); };
  return <AppFrame><PageHeading eyebrow={isDailyChallenge ? "Desafio de hoje" : "Prática inteligente"} title={isDailyChallenge ? "Uma questão. Um passo de consistência." : "Treine. Receba feedback. Ajuste o próximo passo."} description={isDailyChallenge ? "Conclua a questão de treino escolhida para hoje. A conclusão fica guardada no seu percurso." : "Todas as questões desta área são questões de treino criadas para preparação; não são enunciados oficiais de prova."} />{!isDailyChallenge && <section className="mb-6 grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 lg:grid-cols-3"><select value={subject} onChange={(event) => { setSubject(event.target.value as typeof subject); setSelectedModule("all"); setSelectedTopic("all"); }} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm font-semibold text-slate-700"><option value="all">Todas as disciplinas</option><option value="matematica">Matemática</option><option value="fisica">Física</option><option value="quimica">Química</option><option value="geometria">Desenho e Geometria</option><option value="portugues">Língua Portuguesa</option><option value="cultura">Cultura Geral</option></select><select value={selectedModule} onChange={(event) => { setSelectedModule(event.target.value); setSelectedTopic("all"); }} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm font-semibold text-slate-700"><option value="all">Todos os módulos</option>{availableModules.map((module) => <option key={module.id} value={module.id}>{module.title}</option>)}</select><select value={selectedTopic} onChange={(event) => setSelectedTopic(event.target.value)} disabled={selectedModule === "all"} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm font-semibold text-slate-700 disabled:bg-slate-50"><option value="all">Todos os tópicos</option>{moduleTopics.map((topic) => <option key={topic} value={topic}>{topic}</option>)}</select><select value={difficulty} onChange={(event) => setDifficulty(event.target.value as typeof difficulty)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm font-semibold text-slate-700"><option value="all">Todas as dificuldades</option><option value="Inicial">Inicial</option><option value="Intermédio">Intermédio</option><option value="Avançado">Avançado</option></select><label className="flex h-10 items-center justify-between rounded-xl border border-slate-200 px-3 text-sm font-semibold text-slate-600">Apenas erros <Switch checked={onlyIncorrect} onCheckedChange={setOnlyIncorrect} /></label><label className="flex h-10 items-center justify-between rounded-xl border border-slate-200 px-3 text-sm font-semibold text-slate-600">Não respondidas <Switch checked={onlyUnanswered} onCheckedChange={setOnlyUnanswered} /></label><label className="flex h-10 items-center justify-between rounded-xl border border-slate-200 px-3 text-sm font-semibold text-slate-600">Favoritas <Switch checked={favoritesOnly} onCheckedChange={setFavoritesOnly} /></label><p className="flex items-center justify-center text-sm font-bold text-[#0A36A8]">{questions.length} disponíveis</p></section>}{query.isLoading ? <DashboardSkeleton /> : question ? <QuestionWorkspace key={question.id} question={question} result={result} busy={submit.isPending || completeDaily.isPending} favorited={favoriteQuestionIds.has(question.id)} onToggleFavorite={() => toggleFavorite.mutate({ resourceType: "question", resourceId: question.id })} onAnswer={answer} onRetry={() => setResult(null)} onNext={() => { setResult(null); setIndex((current) => (current + 1) % questions.length); }} /> : <EmptyState icon={ListChecks} title="Não há questões para este filtro" description={onlyIncorrect || onlyUnanswered || favoritesOnly ? "Altere os filtros para ampliar a sessão de prática." : "Experimente outra disciplina ou dificuldade."} action={<Button onClick={() => { setOnlyIncorrect(false); setOnlyUnanswered(false); setFavoritesOnly(false); setDifficulty("all"); setSubject("all"); setSelectedModule("all"); setSelectedTopic("all"); }}>Limpar filtros</Button>} />}</AppFrame>;
}

export function ReviewPage() {
  const [, setLocation] = useLocation();
  const review = trpc.learning.review.useQuery();
  const schedule = trpc.learning.reviewSchedule.useQuery();
  const grouped = useMemo(() => { const entries = review.data || []; return Object.values(entries.reduce<Record<string, typeof entries>>((acc, entry) => { const key = entry.attempt.moduleId; acc[key] = [...(acc[key] || []), entry]; return acc; }, {})); }, [review.data]);
  const scheduled = schedule.data ?? [];
  return <AppFrame><PageHeading eyebrow="Meus erros" title="Transforme cada erro numa pista de estudo." description="A revisão reúne tentativas incorrectas e devolve cada tópico no momento certo para consolidar a memória." action={<div className="flex flex-wrap gap-2"><PdfExportModal defaultType="errors" triggerButton={<Button variant="outline" className="gap-2 rounded-xl border-rose-200 bg-rose-50 text-rose-700 hover:bg-rose-100"><FileText className="h-4 w-4" />Exportar Ficha de Erros</Button>} /><Button onClick={() => setLocation("/app/praticar")} className="rounded-xl">Praticar novamente</Button></div>} />{review.isLoading || schedule.isLoading ? <DashboardSkeleton /> : <><section className="mb-6 grid gap-4 md:grid-cols-2"><article className="rounded-2xl border border-[#D8E2FF] bg-[#F4F7FF] p-5"><p className="app-kicker text-[#0A36A8]">Revisão recomendada</p><h2 className="mt-2 font-display text-2xl text-slate-950">{scheduled.filter((item) => item.due).length} tópicos para hoje</h2><p className="mt-2 text-sm leading-6 text-slate-700">Erros regressam no dia seguinte; tópicos acertados voltam após três dias para manter a retenção.</p></article><article className="rounded-2xl border border-amber-100 bg-[#FFFAEF] p-5"><p className="app-kicker text-[#C77A00]">Próximas sessões</p><div className="mt-3 space-y-2">{scheduled.slice(0, 3).map((item) => <button key={`${item.topic}-${item.questionId}`} onClick={() => setLocation(`/app/praticar?question=${item.questionId}`)} className="block w-full rounded-xl bg-white px-3 py-2 text-left text-sm font-bold text-slate-800 hover:bg-amber-50">{item.topic}<span className="ml-2 text-xs font-medium text-slate-500">{item.due ? "Disponível agora" : `Em ${new Date(item.dueAt).toLocaleDateString("pt-PT")}`}</span></button>)}{!scheduled.length && <p className="text-sm text-slate-600">Responda uma questão para criar a sua agenda.</p>}</div></article></section>{grouped.length ? <section className="grid gap-4">{grouped.map((entries) => { const first = entries[0]; return <article key={first.attempt.moduleId} className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p className="app-kicker text-rose-500">{entries.length} {entries.length === 1 ? "erro" : "erros"} a rever</p><h2 className="mt-1 text-xl font-bold text-slate-950">{first.question?.topic}</h2><p className="mt-1 text-sm text-slate-600">Módulo: {first.attempt.moduleId.replaceAll("-", " ")}</p></div><Button variant="outline" onClick={() => setLocation(`/app/praticar?module=${first.attempt.moduleId}&errors=1`)} className="rounded-xl">Fazer sessão de correção <ArrowRight className="ml-1 h-4 w-4" /></Button></div><div className="mt-4 grid gap-3 md:grid-cols-2">{entries.slice(0, 4).map((entry) => <div key={entry.attempt.id} className="rounded-xl bg-rose-50 p-4"><p className="text-sm font-semibold leading-6 text-slate-800">{entry.question?.prompt}</p><p className="mt-2 text-xs text-slate-500">Respondida em {new Date(entry.attempt.createdAt).toLocaleDateString("pt-PT")}</p></div>)}</div></article>; })}</section> : <EmptyState icon={CheckCircle2} title="Sem erros guardados por agora" description="Quando uma questão for respondida incorrectamente, ela aparecerá aqui para uma revisão dirigida." action={<Button onClick={() => setLocation("/app/praticar")}>Começar a praticar</Button>} />}</>}</AppFrame>;
}

export function SimulationsPage() {
  const [, setLocation] = useLocation();
  const [count, setCount] = useState(8);
  const [discipline, setDiscipline] = useState<"all" | "matematica" | "fisica" | "quimica" | "geometria" | "portugues" | "cultura">("all");
  const [mode, setMode] = useState<"practice" | "exam">("practice");
  const start = () => setLocation(`/app/simulado?count=${count}&mode=${mode}${discipline === "all" ? "" : `&discipline=${discipline}`}`);
  return <AppFrame><PageHeading eyebrow="Simulados" title="Teste a sua preparação em contexto." description="O modo prática mostra explicações depois do resultado. O Modo Exame oculta respostas, pistas e LUANDA AI até ao final." action={<PdfExportModal defaultType="exam" triggerButton={<Button variant="outline" className="gap-2 rounded-xl border-[#BFD0FF] bg-white text-[#0A36A8] hover:bg-blue-50"><FileText className="h-4 w-4" />Exportar Prova Impressa</Button>} />} /><section className="grid gap-6 xl:grid-cols-[1.2fr_0.8fr]"><section className="rounded-3xl bg-[#0D1C4D] p-7 text-white sm:p-9"><p className="app-kicker text-[#FFCC5C]">Configurar simulado</p><h2 className="mt-2 font-display text-4xl">Foco, tempo e decisão.</h2><div className="mt-7 space-y-5"><label className="block"><span className="mb-2 block text-sm font-bold text-blue-100">Quantidade de questões</span><select value={count} onChange={(event) => setCount(Number(event.target.value))} className="h-11 w-full rounded-xl border border-blue-300/40 bg-white/10 px-3 text-sm font-bold text-white"><option value={5} className="text-slate-900">5 questões</option><option value={8} className="text-slate-900">8 questões</option><option value={12} className="text-slate-900">12 questões</option><option value={15} className="text-slate-900">15 questões</option></select></label><label className="block"><span className="mb-2 block text-sm font-bold text-blue-100">Disciplina</span><select value={discipline} onChange={(event) => setDiscipline(event.target.value as typeof discipline)} className="h-11 w-full rounded-xl border border-blue-300/40 bg-white/10 px-3 text-sm font-bold text-white"><option value="all" className="text-slate-900">Programa misto</option><option value="matematica" className="text-slate-900">Matemática</option><option value="fisica" className="text-slate-900">Física</option><option value="quimica" className="text-slate-900">Química</option><option value="geometria" className="text-slate-900">Desenho e Geometria</option><option value="portugues" className="text-slate-900">Língua Portuguesa</option><option value="cultura" className="text-slate-900">Cultura Geral</option></select></label><div className="grid grid-cols-2 gap-3"><button onClick={() => setMode("practice")} className={`rounded-2xl border p-4 text-left ${mode === "practice" ? "border-[#FFCC5C] bg-white/10" : "border-white/15 bg-white/5"}`}><Lightbulb className="h-5 w-5 text-[#FFCC5C]" /><p className="mt-3 text-sm font-bold">Modo prática</p><p className="mt-1 text-xs leading-5 text-blue-100">Aprenda com resultado e explicação.</p></button><button onClick={() => setMode("exam")} className={`rounded-2xl border p-4 text-left ${mode === "exam" ? "border-[#FFCC5C] bg-white/10" : "border-white/15 bg-white/5"}`}><LockKeyhole className="h-5 w-5 text-[#FFCC5C]" /><p className="mt-3 text-sm font-bold">Modo Exame</p><p className="mt-1 text-xs leading-5 text-blue-100">Sem respostas ou assistência durante a prova.</p></button></div></div><Button onClick={start} className="mt-7 rounded-xl bg-white text-[#0A36A8] hover:bg-blue-50">Iniciar simulado <ArrowRight className="ml-1 h-4 w-4" /></Button></section><aside className="rounded-3xl border border-slate-200 bg-white p-7"><p className="app-kicker text-slate-400">Como funciona</p><h2 className="mt-2 font-display text-3xl text-slate-950">O resultado mostra o caminho, não só a nota.</h2><div className="mt-6 space-y-5">{[[TimerReset, "Cronómetro", "Acompanhe o ritmo sem perder a concentração."], [Flag, "Marcação", "Use a navegação para regressar a itens incertos."], [BarChart3, "Relatório", "Veja acerto por disciplina e uma recomendação concreta."]].map(([Icon, title, description]) => <div key={String(title)} className="flex gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-[#E7EDFF] text-[#0A36A8]"><Icon className="h-4 w-4" /></span><div><p className="font-bold text-slate-900">{String(title)}</p><p className="mt-1 text-sm leading-5 text-slate-600">{String(description)}</p></div></div>)}</div><p className="mt-7 rounded-xl bg-slate-50 p-4 text-xs leading-5 text-slate-500">Os simulados usam questões de treino da plataforma e não representam uma prova oficial ou previsão de aprovação.</p></aside></section></AppFrame>;
}

function SimulationReport({ finished, onRestart }: { finished: any; onRestart: () => void }) {
  return <AppFrame><PageHeading eyebrow="Resultado do simulado" title={`${finished.percent}% de acerto`} description="Use este relatório para decidir o que rever antes da próxima sessão." action={<Button onClick={onRestart} className="rounded-xl">Novo simulado</Button>} /><section className="grid gap-5 lg:grid-cols-[1.1fr_0.9fr]"><div className="rounded-3xl bg-[#0D1C4D] p-7 text-white"><p className="app-kicker text-[#FFCC5C]">Resumo</p><div className="mt-5 grid grid-cols-3 gap-3">{[["Correctas", finished.correct], ["Incorrectas", finished.incorrect], ["Tempo", formatTime(finished.durationSeconds)]].map(([label, value]) => <div key={String(label)} className="rounded-2xl bg-white/10 p-4"><p className="text-xs text-blue-100">{label}</p><p className="mt-1 text-2xl font-extrabold">{value}</p></div>)}</div><p className="mt-6 text-sm leading-6 text-blue-100">{finished.recommendation}</p></div><div className="rounded-3xl border border-slate-200 bg-white p-6"><p className="app-kicker text-slate-400">Desempenho por disciplina</p><div className="mt-5 space-y-4">{finished.byDiscipline.map((item: any) => <div key={item.id}><div className="mb-2 flex justify-between text-sm font-semibold"><span>{item.label}</span><span>{item.correct}/{item.total}</span></div><ProgressBar value={Math.round((item.correct / item.total) * 100)} tone={item.id === "matematica" ? "blue" : item.id === "portugues" ? "violet" : "green"} /></div>)}</div></div></section><section className="mt-6 rounded-3xl border border-slate-200 bg-white p-6"><p className="app-kicker text-slate-400">Desempenho por tópico</p><div className="mt-5 grid gap-3 sm:grid-cols-2">{finished.byTopic.map((item: any) => <div key={item.topic} className="rounded-xl bg-slate-50 p-4"><div className="flex justify-between gap-3 text-sm font-bold text-slate-800"><span>{item.topic}</span><span>{item.correct}/{item.total}</span></div><div className="mt-3"><ProgressBar value={Math.round((item.correct / item.total) * 100)} tone={item.correct === item.total ? "green" : "amber"} /></div></div>)}</div></section><section className="mt-6 space-y-3">{finished.results.map((item: any, index: number) => <details key={item.question.id} className="rounded-2xl border border-slate-200 bg-white p-5"><summary className="cursor-pointer list-none font-bold text-slate-900"><span className={`mr-2 inline-block h-2 w-2 rounded-full ${item.isCorrect ? "bg-emerald-500" : "bg-rose-500"}`} />Questão {index + 1}: {item.isCorrect ? "Correcta" : "A rever"}</summary><p className="mt-3 text-sm leading-6 text-slate-700">{item.question.prompt}</p><p className="mt-2 text-sm leading-6 text-slate-600">{item.explanation}</p></details>)}</section></AppFrame>;
}

export function ExamSessionPage() {
  const [, setLocation] = useLocation();
  const params = new URLSearchParams(typeof window === "undefined" ? "" : window.location.search);
  const count = Math.min(15, Math.max(3, Number(params.get("count") || 8)));
  const mode = params.get("mode") === "exam" ? "exam" : "practice";
  const discipline = params.get("discipline") as "matematica" | "fisica" | "quimica" | "geometria" | "portugues" | "cultura" | null;
  const moduleId = params.get("module") || undefined;
  const topic = params.get("topic") || undefined;
  const difficulty = params.get("difficulty") as "Inicial" | "Intermédio" | "Avançado" | null;
  const query = params.get("q") || undefined;
  const simulation = trpc.learning.simulation.start.useQuery({ count, disciplineId: discipline || undefined, moduleId, topic, difficulty: difficulty || undefined, query });
  const submit = trpc.learning.simulation.submit.useMutation();
  const utils = trpc.useUtils();
  const [index, setIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [startedAt] = useState(Date.now());
  const [finished, setFinished] = useState<any>(null);
  const [confirmFinish, setConfirmFinish] = useState(false);
  const questions = (simulation.data || []) as PublicQuestion[];
  const question = questions[index];
  const saveAnswer = (option: number) => setAnswers((current) => ({ ...current, [question.id]: option }));
  const finish = () => { if (!questions.length) return; if (!confirmFinish) { setConfirmFinish(true); return; } submit.mutate({ mode, durationSeconds: Math.round((Date.now() - startedAt) / 1000), answers: questions.map((item) => ({ questionId: item.id, selectedOption: answers[item.id] ?? -1 })).filter((item) => item.selectedOption >= 0) }, { onSuccess: (data) => { setFinished(data); utils.learning.dashboard.invalidate(); utils.learning.review.invalidate(); utils.learning.reviewSchedule.invalidate(); } }); };
  if (finished) return <SimulationReport finished={finished} onRestart={() => setLocation("/app/simulados")} />;
  if (finished) return <AppFrame><PageHeading eyebrow="Resultado do simulado" title={`${finished.percent}% de acerto`} description="Use este relatório para decidir o que rever antes da próxima sessão." action={<Button onClick={() => setLocation("/app/simulados")} className="rounded-xl">Novo simulado</Button>} /><section className="grid gap-5 lg:grid-cols-[1.1fr_0.9fr]"><div className="rounded-3xl bg-[#0D1C4D] p-7 text-white"><p className="app-kicker text-[#FFCC5C]">Resumo</p><div className="mt-5 grid grid-cols-3 gap-3">{[["Correctas", finished.correct], ["Incorrectas", finished.incorrect], ["Tempo", formatTime(finished.durationSeconds)]].map(([label, value]) => <div key={String(label)} className="rounded-2xl bg-white/10 p-4"><p className="text-xs text-blue-100">{label}</p><p className="mt-1 text-2xl font-extrabold">{value}</p></div>)}</div><p className="mt-6 text-sm leading-6 text-blue-100">{finished.recommendation}</p></div><div className="rounded-3xl border border-slate-200 bg-white p-6"><p className="app-kicker text-slate-400">Desempenho por disciplina</p><div className="mt-5 space-y-4">{finished.byDiscipline.map((item: any) => <div key={item.id}><div className="mb-2 flex justify-between text-sm font-semibold"><span>{item.label}</span><span>{item.correct}/{item.total}</span></div><ProgressBar value={Math.round((item.correct / item.total) * 100)} tone={item.id === "matematica" ? "blue" : item.id === "portugues" ? "violet" : "green"} /></div>)}</div></div></section><section className="mt-6 space-y-3">{finished.results.map((item: any, i: number) => <details key={item.question.id} className="rounded-2xl border border-slate-200 bg-white p-5"><summary className="cursor-pointer list-none font-bold text-slate-900"><span className={`mr-2 inline-block h-2 w-2 rounded-full ${item.isCorrect ? "bg-emerald-500" : "bg-rose-500"}`} />Questão {i + 1}: {item.isCorrect ? "Correcta" : "A rever"}</summary><p className="mt-3 text-sm leading-6 text-slate-700">{item.question.prompt}</p><p className="mt-2 text-sm leading-6 text-slate-600">{item.explanation}</p></details>)}</section></AppFrame>;
  if (simulation.isLoading || !question) return <AppFrame><DashboardSkeleton /></AppFrame>;
  if (confirmFinish) return <AppFrame><PageHeading eyebrow="Confirmar simulado" title="Quer finalizar agora?" description={`Respondeu ${Object.keys(answers).length} de ${questions.length} questões. O resultado será guardado no seu percurso.`} /><section className="mx-auto max-w-2xl rounded-3xl border border-amber-200 bg-[#FFFAEF] p-7"><p className="text-sm leading-7 text-slate-700">Depois da confirmação, verá os acertos, os erros, o tempo, o desempenho por disciplina e os tópicos a rever.</p><div className="mt-6 flex flex-wrap gap-3"><Button onClick={finish} disabled={submit.isPending} className="rounded-xl bg-[#0A36A8]">{submit.isPending ? "A finalizar…" : "Confirmar e ver resultado"}</Button><Button variant="outline" onClick={() => setConfirmFinish(false)} className="rounded-xl">Continuar o simulado</Button></div></section></AppFrame>;
  const selected = answers[question.id];
  return <AppFrame><section className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><p className="app-kicker">{mode === "exam" ? "Modo Exame" : "Simulado de prática"}</p><p className="mt-1 text-sm font-semibold text-slate-600">Questão {index + 1} de {questions.length} · {Object.keys(answers).length} respondidas</p></div><div className="rounded-xl bg-white px-4 py-2 text-sm font-extrabold text-[#0A36A8] shadow-sm"><Clock3 className="mr-1 inline h-4 w-4" />{formatTime(Math.round((Date.now() - startedAt) / 1000))}</div></section><section className="grid gap-6 xl:grid-cols-[1fr_280px]"><div className="rounded-3xl border border-slate-200 bg-white p-6 sm:p-8"><p className="text-xs font-bold uppercase tracking-[0.14em] text-slate-400">Questão de treino · {question.topic}</p><h1 className="mt-3 text-xl font-bold leading-8 text-slate-950 sm:text-2xl">{question.prompt}</h1><div className="mt-6 grid gap-3">{question.options.map((option, optionIndex) => <button key={option} onClick={() => saveAnswer(optionIndex)} className={`flex items-start gap-3 rounded-2xl border p-4 text-left text-sm font-semibold transition-colors ${selected === optionIndex ? "border-[#0A36A8] bg-[#EEF2FF] text-[#0A36A8]" : "border-slate-200 text-slate-700 hover:border-[#BFD0FF]"}`}><span className="grid h-6 w-6 shrink-0 place-items-center rounded-full border border-current text-xs">{String.fromCharCode(65 + optionIndex)}</span><span className="pt-0.5 leading-6">{option}</span></button>)}</div><div className="mt-7 flex flex-wrap justify-between gap-3"><Button variant="outline" disabled={index === 0} onClick={() => setIndex((current) => Math.max(0, current - 1))} className="rounded-xl"><ArrowLeft className="mr-1 h-4 w-4" />Anterior</Button>{index === questions.length - 1 ? <Button onClick={finish} disabled={submit.isPending} className="rounded-xl bg-[#0A36A8]">{submit.isPending ? "A finalizar…" : "Finalizar simulado"}<Check className="ml-1 h-4 w-4" /></Button> : <Button onClick={() => setIndex((current) => Math.min(questions.length - 1, current + 1))} className="rounded-xl">Próxima<ArrowRight className="ml-1 h-4 w-4" /></Button>}</div></div><aside className="rounded-3xl border border-slate-200 bg-white p-5"><p className="app-kicker text-slate-400">Navegação</p><div className="mt-4 grid grid-cols-5 gap-2">{questions.map((item, itemIndex) => <button key={item.id} onClick={() => setIndex(itemIndex)} className={`grid h-9 place-items-center rounded-lg text-xs font-extrabold ${index === itemIndex ? "bg-[#0A36A8] text-white" : answers[item.id] !== undefined ? "bg-[#E2F6F0] text-[#087765]" : "bg-slate-100 text-slate-500"}`}>{itemIndex + 1}</button>)}</div>{mode === "exam" && <p className="mt-5 rounded-xl bg-amber-50 p-3 text-xs leading-5 text-amber-900"><LockKeyhole className="mr-1 inline h-3.5 w-3.5" />No Modo Exame, respostas e assistência são apresentadas apenas no final.</p>}</aside></section></AppFrame>;
}

export function AiPage() {
  const searchParams = new URLSearchParams(typeof window === "undefined" ? "" : window.location.search);
  const questionId = searchParams.get("question") || undefined;
  const moduleId = searchParams.get("module") || undefined;
  const conversations = trpc.ai.conversations.useQuery();
  const [conversationId, setConversationId] = useState<number | undefined>();
  const storedMessages = trpc.ai.messages.useQuery({ conversationId: conversationId || 0 }, { enabled: Boolean(conversationId) });
  const chat = trpc.ai.chat.useMutation();
  const [localMessages, setLocalMessages] = useState<Message[]>([]);
  const [mode, setMode] = useState<"explain" | "simple" | "example" | "steps" | "analogy" | "exercise" | "quiz" | "exam">("explain");
  const [exerciseDiscipline, setExerciseDiscipline] = useState("Matemática");
  const [exerciseTopic, setExerciseTopic] = useState("");
  const [exerciseDifficulty, setExerciseDifficulty] = useState("Intermédio");
  const [exerciseCount, setExerciseCount] = useState(3);
  useEffect(() => { if (storedMessages.data) setLocalMessages(storedMessages.data.map((item) => ({ role: item.role, content: item.content }))); }, [storedMessages.data]);
  const send = (content: string) => { setLocalMessages((current) => [...current, { role: "user", content }]); chat.mutate({ message: content, conversationId, moduleId, questionId, mode }, { onSuccess: (response) => { setConversationId(response.conversationId); setLocalMessages((current) => [...current, response.message]); conversations.refetch(); }, onError: () => setLocalMessages((current) => [...current, { role: "assistant", content: "Não consegui responder agora. Tente reformular a pergunta em instantes." }]) }); };
  return <AppFrame><PageHeading eyebrow="LUANDA AI" title="Raciocine com apoio, não apenas com resposta." description="O tutor usa o contexto da sua pergunta e privilegia pistas, passos e verificação do raciocínio. As explicações são complementares ao programa." /><section className="grid gap-6 xl:grid-cols-[280px_1fr]"><aside className="rounded-3xl border border-slate-200 bg-white p-5"><p className="app-kicker text-slate-400">Condução da sessão</p><div className="mt-4 grid gap-2">{[["explain", "Explicar"], ["steps", "Passo a passo"], ["simple", "Mais simples"], ["example", "Dar exemplo"], ["analogy", "Usar analogia"], ["exercise", "Criar exercício"], ["quiz", "Mini quiz"]].map(([value, label]) => <button key={value} onClick={() => setMode(value as typeof mode)} className={`rounded-xl px-3 py-2 text-left text-sm font-bold ${mode === value ? "bg-[#E7EDFF] text-[#0A36A8]" : "text-slate-600 hover:bg-slate-50"}`}>{label}</button>)}</div>{mode === "exercise" && <div className="mt-4 space-y-2 rounded-2xl bg-[#F4F7FF] p-3"><p className="text-xs font-extrabold uppercase tracking-[0.12em] text-[#0A36A8]">Gerador de exercícios</p><select value={exerciseDiscipline} onChange={(event) => setExerciseDiscipline(event.target.value)} className="h-9 w-full rounded-lg border border-[#D8E2FF] bg-white px-2 text-xs font-semibold"><option>Matemática</option><option>Física</option><option>Química</option><option>Desenho e Geometria Descritiva</option><option>Língua Portuguesa</option><option>Cultura Geral</option></select><input value={exerciseTopic} onChange={(event) => setExerciseTopic(event.target.value)} placeholder="Assunto ou tópico (opcional)" className="h-9 w-full rounded-lg border border-[#D8E2FF] bg-white px-2 text-xs" /><div className="grid grid-cols-2 gap-2"><select value={exerciseDifficulty} onChange={(event) => setExerciseDifficulty(event.target.value)} className="h-9 rounded-lg border border-[#D8E2FF] bg-white px-2 text-xs font-semibold"><option>Inicial</option><option>Intermédio</option><option>Avançado</option></select><select value={exerciseCount} onChange={(event) => setExerciseCount(Number(event.target.value))} className="h-9 rounded-lg border border-[#D8E2FF] bg-white px-2 text-xs font-semibold"><option value={1}>1 questão</option><option value={3}>3 questões</option><option value={5}>5 questões</option></select></div><Button onClick={() => send(`Gera ${exerciseCount} questões de treino de ${exerciseDiscipline}${exerciseTopic ? ` sobre ${exerciseTopic}` : ""}, com dificuldade ${exerciseDifficulty}. Para cada uma, separa enunciado, resposta e explicação.`)} disabled={chat.isPending} className="w-full rounded-lg bg-[#0A36A8] text-xs text-white">Gerar agora</Button></div>}<div className="mt-6 border-t border-slate-100 pt-5"><p className="app-kicker text-slate-400">Conversas</p><div className="mt-3 space-y-1">{conversations.data?.slice().reverse().slice(0, 5).map((conversation) => <button key={conversation.id} onClick={() => setConversationId(conversation.id)} className={`w-full truncate rounded-lg px-2 py-2 text-left text-xs font-semibold ${conversationId === conversation.id ? "bg-slate-100 text-slate-900" : "text-slate-500 hover:bg-slate-50"}`}>{conversation.title}</button>)}</div><Button variant="outline" onClick={() => { setConversationId(undefined); setLocalMessages([]); }} className="mt-3 w-full rounded-xl text-xs">Nova conversa</Button></div></aside><section className="overflow-hidden rounded-3xl border border-slate-200 bg-white"><div className="flex items-center gap-3 border-b border-slate-100 px-5 py-4"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#E7EDFF] text-[#0A36A8]"><BrainCircuit className="h-5 w-5" /></span><div><p className="font-bold text-slate-900">LUANDA AI</p><p className="text-xs text-slate-500">Modo: {mode === "steps" ? "Passo a passo" : mode}</p></div></div><AIChatBox messages={localMessages} onSendMessage={send} isLoading={chat.isPending} height="620px" placeholder="Escreva a sua dúvida…" emptyStateMessage={questionId ? "Explique onde ficou bloqueado nesta questão de treino." : "Comece com uma dúvida sobre o seu estudo."} suggestedPrompts={questionId ? ["Dá-me apenas a primeira pista.", "Que conceito devo rever?", "Mostra o raciocínio passo a passo."] : ["Ajuda-me a montar um plano de estudo.", "Explica domínio de uma função com um exemplo.", "Cria uma questão de treino de lógica."]} /></section></section></AppFrame>;
}

export function PlanPage() {
  const [, setLocation] = useLocation();
  const plan = trpc.learning.plan.get.useQuery();
  const save = trpc.learning.plan.save.useMutation({ onSuccess: () => plan.refetch() });
  const reset = trpc.learning.plan.reset.useMutation({ onSuccess: () => plan.refetch() });
  const [tasks, setTasks] = useState<{ id: string; label: string; minutes: number; done: boolean; moduleId?: string }[]>([]);
  const [minutes, setMinutes] = useState(45);
  useEffect(() => { if (plan.data) { setTasks(plan.data.tasks as typeof tasks); setMinutes(plan.data.dailyMinutes); } }, [plan.data]);
  const updateTask = (id: string) => { const next = tasks.map((task) => task.id === id ? { ...task, done: !task.done } : task); setTasks(next); save.mutate({ title: plan.data?.title || "Plano de preparação", dailyMinutes: minutes, tasks: next }); };
  const addTask = () => { const task = { id: `custom-${Date.now()}`, label: "Nova sessão de revisão", minutes: 20, done: false }; const next = [...tasks, task]; setTasks(next); save.mutate({ title: plan.data?.title || "Plano de preparação", dailyMinutes: minutes, tasks: next }); };
  const completed = tasks.filter((task) => task.done).length;
  return <AppFrame><PageHeading eyebrow="Plano de estudo" title="Uma rotina semanal, repetida com intenção." description="O ciclo alterna aprender, desafiar, recuperar erros e consolidar. Conclua uma sessão por vez e ajuste o tempo ao seu ritmo." action={<div className="rounded-xl border border-slate-200 bg-white px-4 py-2 text-sm font-bold text-slate-700"><CalendarClock className="mr-1.5 inline h-4 w-4 text-[#0A36A8]" />{completed}/{tasks.length} etapas concluídas</div>} /><section className="grid gap-6 xl:grid-cols-[1fr_340px]"><section className="rounded-3xl border border-slate-200 bg-white p-6 sm:p-8"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="app-kicker text-slate-400">{plan.data?.title || "Plano de preparação"}</p><h2 className="mt-1 font-display text-3xl text-slate-950">O seu ciclo de estudo</h2></div><label className="text-sm font-bold text-slate-600">Tempo diário <select value={minutes} onChange={(event) => { const next = Number(event.target.value); setMinutes(next); save.mutate({ title: plan.data?.title || "Plano de preparação", dailyMinutes: next, tasks }); }} className="ml-2 rounded-lg border border-slate-200 bg-white px-2 py-1 text-[#0A36A8]"><option value={30}>30 min</option><option value={45}>45 min</option><option value={60}>60 min</option><option value={90}>90 min</option></select></label></div><div className="mt-7 space-y-3">{tasks.map((task, index) => <div key={task.id} className={`flex items-center gap-4 rounded-2xl border p-4 ${task.done ? "border-emerald-100 bg-emerald-50/60" : "border-slate-200 bg-white"}`}><button onClick={() => updateTask(task.id)} className={`grid h-7 w-7 shrink-0 place-items-center rounded-full border ${task.done ? "border-emerald-600 bg-emerald-600 text-white" : "border-slate-300 text-transparent"}`}><Check className="h-4 w-4" /></button><div className="min-w-0 flex-1"><p className={`font-bold ${task.done ? "text-emerald-900 line-through" : "text-slate-900"}`}>{index + 1}. {task.label}</p><p className="mt-1 text-xs text-slate-500">{task.minutes} minutos recomendados</p></div>{task.moduleId && <Button variant="outline" size="sm" onClick={() => setLocation(`/app/aula/${task.moduleId}`)} className="rounded-xl">Abrir</Button>}</div>)}</div><div className="mt-5 flex flex-wrap gap-3"><Button variant="outline" onClick={addTask} className="rounded-xl"><Plus className="mr-1 h-4 w-4" />Adicionar sessão</Button><Button variant="ghost" onClick={() => reset.mutate()} disabled={reset.isPending} className="rounded-xl text-slate-600">{reset.isPending ? "A actualizar…" : "Regenerar ciclo"}</Button></div></section><aside className="rounded-3xl bg-[#0D1C4D] p-6 text-white"><p className="app-kicker text-[#FFCC5C]">Ritmo sustentável</p><h2 className="mt-2 font-display text-3xl">Alterne esforço, desafio e revisão.</h2><p className="mt-4 text-sm leading-6 text-blue-100">A retenção melhora quando a aula é seguida por prática curta e quando os erros voltam ao plano antes do próximo simulado.</p><Button onClick={() => setLocation("/app/desafios")} className="mt-6 rounded-xl bg-white text-[#0A36A8] hover:bg-blue-50">Abrir desafios</Button></aside></section></AppFrame>;
}

export function ProgressPage() {
  const [, setLocation] = useLocation();
  const dashboard = trpc.learning.dashboard.useQuery();
  const weeklyActivity = trpc.learning.progress.weeklyActivity.useQuery();
  const modules = dashboard.data?.moduleProgress || [];
  const weeklyStats = weeklyActivity.data || [];
  const maxWeeklyMinutes = Math.max(1, ...weeklyStats.map((day) => day.minutes));
  const totalWeeklyMinutes = weeklyStats.reduce((total, day) => total + day.minutes, 0);
  const formatWeekday = (date: string) => new Date(`${date}T12:00:00Z`).toLocaleDateString("pt-PT", { weekday: "short", timeZone: "UTC" }).replace(".", "");
  const levels = [[0, 30, "Inicial"], [31, 50, "Básico"], [51, 70, "Em desenvolvimento"], [71, 85, "Bom"], [86, 95, "Muito bom"], [96, 100, "Dominado"]];
  return <AppFrame><PageHeading eyebrow="Progresso" title="Veja o padrão por trás dos seus resultados." description="O domínio combina desempenho nas questões, avanço marcado na aula e recência de estudo. Não é uma previsão de aprovação." /><section className="grid gap-5 lg:grid-cols-3"><StatCard label="Índice de preparação" value={`${dashboard.data?.stats.preparationIndex ?? 0}%`} hint="Média dos módulos do seu percurso." icon={Target} /><StatCard label="Taxa de acerto" value={`${dashboard.data?.stats.accuracy ?? 0}%`} hint="Em todas as questões respondidas." icon={Trophy} tone="green" /><StatCard label="Simulados" value={dashboard.data?.stats.simulations ?? 0} hint="Tentativas concluídas e guardadas." icon={TimerReset} tone="violet" /></section><section className="mt-6 rounded-3xl border border-slate-200 bg-white p-6 sm:p-7"><div className="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between"><div><p className="app-kicker text-slate-400">Ritmo semanal</p><h2 className="mt-1 font-display text-3xl text-slate-950">Tempo de estudo</h2><p className="mt-2 text-sm leading-6 text-slate-600">Minutos registados nas respostas de treino e nos simulados dos últimos sete dias.</p></div><div className="rounded-2xl bg-[#E7EDFF] px-4 py-3 text-right"><p className="text-xs font-bold uppercase tracking-[0.12em] text-[#0A36A8]">Total da semana</p><p className="mt-1 text-2xl font-extrabold text-slate-950">{totalWeeklyMinutes} min</p></div></div>{weeklyActivity.isLoading ? <div className="mt-8 h-44 animate-pulse rounded-2xl bg-slate-100" /> : weeklyActivity.error ? <div className="mt-6 rounded-2xl border border-rose-100 bg-rose-50 p-4 text-sm text-rose-700">Não foi possível carregar o ritmo semanal agora. Tente novamente mais tarde.</div> : <div className="mt-8" role="img" aria-label="Gráfico de minutos de estudo por dia nos últimos sete dias"><div className="flex h-48 items-end gap-2 sm:gap-4">{weeklyStats.map((day) => { const height = day.minutes ? Math.max(10, Math.round((day.minutes / maxWeeklyMinutes) * 100)) : 4; return <div key={day.date} className="flex min-w-0 flex-1 flex-col items-center gap-2"><div className="flex h-36 w-full items-end justify-center"><div title={`${day.minutes} minutos em ${day.date}`} className={`w-full max-w-12 rounded-t-xl transition-all ${day.minutes ? "bg-[#0A36A8]" : "bg-slate-100"}`} style={{ height: `${height}%` }} /></div><span className="text-[0.68rem] font-bold capitalize text-slate-500">{formatWeekday(day.date)}</span><span className="text-xs font-extrabold text-slate-900">{day.minutes}m</span></div>; })}</div><p className="mt-5 text-xs leading-5 text-slate-500">Cada barra representa a duração efectivamente registada no sistema. Dias sem actividade aparecem a zero.</p></div>}</section><section className="mt-6 grid gap-6 xl:grid-cols-[1fr_330px]"><div className="rounded-3xl border border-slate-200 bg-white p-6"><p className="app-kicker text-slate-400">Domínio por módulo</p><div className="mt-6 space-y-5">{modules.map((item) => <button key={item.module.id} onClick={() => setLocation(`/app/aula/${item.module.id}`)} className="block w-full rounded-xl p-2 text-left hover:bg-slate-50"><div className="mb-2 flex justify-between gap-4 text-sm"><span className="font-bold text-slate-800">{item.module.discipline} · {item.module.title}</span><span className="shrink-0 font-extrabold text-[#0A36A8]">{item.mastery}%</span></div><ProgressBar value={item.mastery} tone={item.module.disciplineId === "matematica" ? "blue" : item.module.disciplineId === "portugues" ? "violet" : "green"} /><p className="mt-1.5 text-xs text-slate-500">{item.status === "completed" ? "Aula concluída" : item.status === "in_progress" ? "Em curso" : "Ainda não iniciado"}</p></button>)}</div></div><aside className="rounded-3xl border border-slate-200 bg-white p-6"><p className="app-kicker text-slate-400">Como ler os níveis</p><div className="mt-5 space-y-3">{levels.map(([min, max, label]) => <div key={String(label)} className="flex items-center justify-between rounded-xl bg-slate-50 px-3 py-2"><span className="text-sm font-bold text-slate-700">{label}</span><span className="text-xs font-semibold text-slate-500">{min}–{max}%</span></div>)}</div><p className="mt-5 text-xs leading-5 text-slate-500">Para subir com consistência, combine aula concluída, tentativas e uma revisão após erros.</p></aside></section></AppFrame>;
}

export function ProfilePage() {
  const { user } = useAuth();
  const dashboard = trpc.learning.dashboard.useQuery();
  const utils = trpc.useUtils();
  const save = trpc.learning.profile.save.useMutation({ onSuccess: () => utils.learning.dashboard.invalidate() });
  const { theme, toggleTheme } = useTheme();
  const profile = dashboard.data?.profile;
  const [displayName, setDisplayName] = useState(""); const [examDate, setExamDate] = useState(""); const [dailyMinutes, setDailyMinutes] = useState(45); const [goal, setGoal] = useState("");
  useEffect(() => { if (profile) { setDisplayName(profile.displayName); setExamDate(profile.examDate || ""); setDailyMinutes(profile.dailyMinutes); setGoal(profile.goal || ""); } else if (user?.name) setDisplayName(user.name); }, [profile, user?.name]);
  const submit = (event: React.FormEvent) => { event.preventDefault(); save.mutate({ displayName, examDate: examDate || undefined, dailyMinutes, studyDays: ["Segunda", "Terça", "Quarta", "Quinta", "Sexta"], goal: goal || undefined, theme: theme === "dark" ? "dark" : "light" }); };
  return <AppFrame><PageHeading eyebrow="Perfil e preferências" title="Faça a plataforma trabalhar ao seu ritmo." description="As suas preferências são privadas e servem para personalizar o percurso, o plano e a experiência de leitura." /><section className="grid gap-6 xl:grid-cols-[1fr_360px]"><form onSubmit={submit} className="rounded-3xl border border-slate-200 bg-white p-6 sm:p-8"><div className="grid gap-5 sm:grid-cols-2"><div className="sm:col-span-2"><Label htmlFor="name">Como prefere ser chamado</Label><Input id="name" value={displayName} onChange={(event) => setDisplayName(event.target.value)} className="mt-2 h-11 rounded-xl" required /></div><div><Label htmlFor="email">Email da conta</Label><Input id="email" value={user?.email || "Não disponibilizado pela conta"} className="mt-2 h-11 rounded-xl bg-slate-50" disabled /></div><div><Label htmlFor="date">Data prevista para o exame</Label><Input id="date" type="date" value={examDate} onChange={(event) => setExamDate(event.target.value)} className="mt-2 h-11 rounded-xl" /></div><div><Label htmlFor="minutes">Tempo diário disponível</Label><select id="minutes" value={dailyMinutes} onChange={(event) => setDailyMinutes(Number(event.target.value))} className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm font-semibold"><option value={30}>30 minutos</option><option value={45}>45 minutos</option><option value={60}>60 minutos</option><option value={90}>90 minutos</option></select></div><div className="sm:col-span-2"><Label htmlFor="goal">Meta de preparação</Label><Textarea id="goal" value={goal} onChange={(event) => setGoal(event.target.value)} className="mt-2 min-h-28 rounded-xl" placeholder="Ex.: consolidar matemática e fazer um simulado por semana." /></div></div><Button type="submit" disabled={save.isPending || displayName.trim().length < 2} className="mt-6 rounded-xl bg-[#0A36A8]">{save.isPending ? "A guardar…" : "Guardar preferências"}</Button></form><aside className="space-y-5"><section className="rounded-3xl bg-[#0D1C4D] p-6 text-white"><p className="app-kicker text-[#FFCC5C]">Tema</p><h2 className="mt-2 font-display text-3xl">Leitura confortável, dia ou noite.</h2><div className="mt-5 flex items-center justify-between rounded-2xl bg-white/10 p-4"><div><p className="font-bold">Modo escuro</p><p className="mt-1 text-xs text-blue-100">Actual: {theme === "dark" ? "escuro" : "claro"}</p></div><Switch checked={theme === "dark"} onCheckedChange={() => toggleTheme?.()} /></div></section><section className="rounded-3xl border border-slate-200 bg-white p-6"><p className="app-kicker text-slate-400">Privacidade</p><p className="mt-3 text-sm leading-6 text-slate-600">A autenticação usa a conta Manus. O LUANDA PREP não armazena uma palavra-passe própria; guarda apenas o conteúdo necessário ao seu progresso dentro deste projecto.</p></section></aside></section></AppFrame>;
}

function EmptyState({ icon: Icon, title, description, action }: { icon: React.ElementType; title: string; description: string; action?: React.ReactNode }) { return <section className="grid min-h-72 place-items-center rounded-3xl border border-dashed border-slate-300 bg-white p-8 text-center"><div className="max-w-sm"><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-[#E7EDFF] text-[#0A36A8]"><Icon className="h-6 w-6" /></span><h2 className="mt-4 text-xl font-bold text-slate-950">{title}</h2><p className="mt-2 text-sm leading-6 text-slate-600">{description}</p>{action && <div className="mt-5">{action}</div>}</div></section>; }
